mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, id_card = #{idCard}, is_college = #{isCollege}, address = #{address}, degree = #{degree}, update_time = #{updateTime},
where id = #{id}

update student
set violation_count = violation_count + 1,
    violation_score = violation_score + #{score}
where id = #{id}

mapper.select:
select s.*, c.name as clazzName from student s left join clazz c on s.clazz_id = c.id
s.name like concat('%', #{name}, '%')
and s.degree = #{degree}
and s.clazz_id = #{clazzId}
order by s.update_time desc
